# ----------------------------------------------------------------------------------------
# Migración de datos H1-A → esquema v2. Copia congelada de las reglas de ese momento: una
# migración no debe importar código de la aplicación que seguirá cambiando.
#
# Regla de fondo: H1-A suponía "mg" para una cifra suelta (strength_unit_inferred = true) y
# trataba un volumen suelto ("120 ml") como potencia. Esos datos NO se conservan como hechos:
# pasan a `unassigned` (valor conocido, unidad/rol pendientes de validación). Lo explícito
# se conserva como explícito. Los valores normalizados de H1-A quedan como "lo escrito"; el
# texto original está en las observaciones y en `strength_text` (se guarda en original_text).
# ----------------------------------------------------------------------------------------
_LEGACY_STRENGTH_DIMS = {
    "mg": ("mass", "mg"), "ui": ("iu", "ui"), "%": ("percent", "%"), "mg/ml": ("mass/volume", "mg/ml"),
}  # fmt: skip


def _f(d) -> str:
    from decimal import Decimal

    return format(Decimal(d).normalize(), "f")


def _backfill_attributes(conn) -> None:
    import json

    rows = conn.execute(
        sa.text(
            """
        SELECT i.id, i.ingredient, i.display_name, i.strength_value, i.strength_unit, i.strength_text,
               i.strength_unit_inferred, i.dosage_form, i.content_amount, i.release,
               i.resolved_identity_key,
               (SELECT o.raw_text FROM demand_observation o
                 WHERE o.demand_item_id = i.id AND o.organization_id = i.organization_id
                 ORDER BY o.created_at, o.id LIMIT 1) AS first_text
        FROM demand_item i
        """
        )
    ).mappings()
    for r in rows:
        attrs: dict = {"schema_version": 2, "ingredient": r["ingredient"], "strengths": [], "unassigned": []}
        if r["first_text"]:
            attrs["original_text"] = r["first_text"]
        display = r["display_name"]
        skey = None
        sv, su = r["strength_value"], r["strength_unit"]
        if sv is not None:
            solid = su in _LEGACY_STRENGTH_DIMS and not r["strength_unit_inferred"]
            if solid:
                num, _, den = su.partition("/")
                measure = {"value": _f(sv), "unit": num, "original_text": r["strength_text"] or f"{_f(sv)} {su}"}
                if den:
                    measure["per_unit"] = den
                kind = "concentration" if den or su == "%" else "amount_per_unit"
                attrs["strengths"].append({"measure": measure, "kind": kind, "basis": "explicit", "role_rule": "legacy_h1a"})
                dim, base = _LEGACY_STRENGTH_DIMS[su]
                skey = f"{dim}:{_f(sv)}{base}"
            else:
                um = {"value": _f(sv), "original_text": _f(sv)}
                if su and not r["strength_unit_inferred"]:
                    um["unit"] = su  # unidad escrita pero con rol no soportado (p. ej. ml suelto)
                attrs["unassigned"].append(um)
                label = _f(sv) + (f" {um['unit']} (rol por confirmar)" if "unit" in um else " (sin unidad)")
                if r["strength_text"]:
                    display = display.replace(r["strength_text"], label)
        if r["dosage_form"]:
            attrs["form"] = {"value": r["dosage_form"], "basis": "explicit"}
        if r["content_amount"] is not None:
            attrs["content"] = {
                "measure": {"value": str(r["content_amount"]), "unit": "un", "original_text": f"x {r['content_amount']}"},
                "basis": "explicit",
            }
        if r["release"]:
            attrs["release"] = {"value": r["release"], "basis": "explicit"}
        key = None
        if skey and r["dosage_form"] and r["content_amount"] is not None and not attrs["unassigned"]:
            key = f"{r['ingredient']}|{skey}|{r['dosage_form']}|count:{r['content_amount']}un|{r['release'] or '-'}"
        conn.execute(
            sa.text(
                "UPDATE demand_item SET attributes = CAST(:a AS jsonb), display_name = :d, "
                "resolved_identity_key = :k WHERE id = :id"
            ),
            {"a": json.dumps(attrs), "d": display, "k": key, "id": r["id"]},
        )


def _restore_legacy_columns(conn) -> None:
    """Downgrade con pérdida controlada: solo se restaura la primera potencia y el contenido."""
    conn.execute(
        sa.text(
            """
        UPDATE demand_item SET
          dosage_form = attributes #>> '{form,value}',
          release = attributes #>> '{release,value}',
          content_amount = CASE WHEN attributes #>> '{content,measure,unit}' = 'un'
                           THEN (attributes #>> '{content,measure,value}')::numeric::int END,
          strength_value = (attributes #>> '{strengths,0,measure,value}')::numeric,
          strength_unit = (attributes #>> '{strengths,0,measure,unit}')
              || COALESCE('/' || (attributes #>> '{strengths,0,measure,per_unit}'), ''),
          strength_text = attributes #>> '{strengths,0,measure,original_text}'
        """
        )
    )
